with parsed as (select id, aggregate(tier_prices, cast(0 as double), (acc, p) -> acc + p, acc -> round(acc / size(tier_prices), 2)) as avg_tier_price, array_min(tier_prices) as lowest_price, zip_with(tier_prices, discounts, (p, d) -> round(p * (1 - d), 2)) as net_prices, transform(tier_prices, (p, i) -> round(p * tier_limits[i], 2)) as tier_revenue_caps from price_tiers) select case when lowest_price >= 28 then 'PREMIUM' else 'STANDARD' end as lowest_price_tier, count(*) as event_count, min(lowest_price) as min_lowest_price, count(*) as cnt, approx_percentile(avg_tier_price, array(0.25, 0.5, 0.75)) as avg_tier_price_quartiles, approx_percentile(avg_tier_price, 0.5) as avg_tier_price_p50 from parsed group by 1
